// ── CORS headers ───────────────────────────────────────────────────────────
function corsHeaders(origin) {
  // In production, replace '*' with your actual domain e.g. 'https://sreeindiapalace.com'
  return {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Access-Control-Max-Age': '86400',
  }
}

function jsonResponse(data, status = 200, origin) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders(origin), 'Content-Type': 'application/json' },
  })
}

// ── Main handler ───────────────────────────────────────────────────────────
export default {
  async fetch(request, env) {
    const origin = request.headers.get('Origin') || ''

    // Preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders(origin) })
    }

    if (request.method !== 'POST') {
      return jsonResponse({ error: 'Method not allowed' }, 405, origin)
    }

    // ── Rate limit ──
    const ip = request.headers.get('CF-Connecting-IP') ||
               request.headers.get('X-Forwarded-For') ||
               'unknown'

    if (isRateLimited(ip)) {
      return jsonResponse(
        { error: 'Too many requests — even a royal kitchen needs a breather. Try again in a minute.' },
        429, origin
      )
    }

    // ── Parse body ──
    let body
    try {
      body = await request.json()
    } catch {
      return jsonResponse({ error: 'Invalid JSON in request body.' }, 400, origin)
    }

    const { message, history = [] } = body

    // ── Input validation ──
    if (!message || typeof message !== 'string') {
      return jsonResponse({ error: 'message field is required.' }, 400, origin)
    }

    const trimmed = message.trim()
    if (trimmed.length === 0) {
      return jsonResponse({ error: 'Message cannot be empty.' }, 400, origin)
    }
    if (trimmed.length > 600) {
      return jsonResponse({ error: 'Message too long — keep it under 600 characters.' }, 400, origin)
    }

    // ── Build Gemini conversation ──
    // Send last 6 messages (3 turns) for context, exclude chip-nav echoes
    const recentHistory = Array.isArray(history)
      ? history
          .filter(h => h && h.content && typeof h.content === 'string')
          .slice(-6)
          .map(h => ({
            role: h.type === 'user' ? 'user' : 'model',
            parts: [{ text: h.content.slice(0, 400) }], // cap individual history entries
          }))
      : []

    const contents = [
      ...recentHistory,
      { role: 'user', parts: [{ text: trimmed }] },
    ]

    // ── Call Gemini ──
    try {
      const geminiRes = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${env.GEMINI_API_KEY}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
            contents,
            generationConfig: {
              maxOutputTokens: 280,
              temperature: 0.82,
              topP: 0.92,
            },
            safetySettings: [
              { category: 'HARM_CATEGORY_HARASSMENT',        threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
              { category: 'HARM_CATEGORY_HATE_SPEECH',       threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
              { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
              { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
            ],
          }),
        }
      )

      if (!geminiRes.ok) {
        const errBody = await geminiRes.text()
        console.error(`Gemini ${geminiRes.status}:`, errBody)
        return jsonResponse(
          { error: 'The kitchen is a little overwhelmed right now. Try again in a moment!' },
          502, origin
        )
      }

      const data = await geminiRes.json()
      const reply =
        data?.candidates?.[0]?.content?.parts?.[0]?.text?.trim() ||
        "I seem to have misplaced my train of thought. Please try asking again!"

      // Block if Gemini flagged the content
      if (data?.candidates?.[0]?.finishReason === 'SAFETY') {
        return jsonResponse(
          { error: "That topic is a little outside our menu. Let's keep it to food and reservations!" },
          200, origin
        )
      }

      return jsonResponse({ reply }, 200, origin)

    } catch (err) {
      console.error('Worker fetch error:', err)
      return jsonResponse(
        { error: 'Something went wrong on our end. Give it another try!' },
        500, origin
      )
    }
  },
}
